def _positive_int(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError('attempt must be an int')
    if value <= 0:
        raise ValueError('attempt must be positive')
    return value


def _nonneg_int(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError('downloaded_rows must be an int')
    if value < 0:
        raise ValueError('downloaded_rows must be nonnegative')
    return value


def reconcile(rows, asof):
    asof_instant = instant(asof)
    deduped = {}

    for row in rows:
        if not isinstance(row, dict):
            continue
        try:
            run_id = _required(row, 'run_id')
            job = _required(row, 'job')
            status = row.get('status')
            if status not in _VALID_STATUSES:
                continue
            attempt = _positive_int(row.get('attempt'))
            observed_at = instant(row['observed_at'])
            downloaded_rows = _nonneg_int(row.get('downloaded_rows'))
